import{_ as e,o as d,c as o,a2 as a}from"./chunks/framework.BM5YPQmL.js";const g=JSON.parse('{"title":"مرجع سطر الأوامر (CLI)","description":"","frontmatter":{"editLink":false},"headers":[],"relativePath":"ar/reference/cli.md","filePath":"ar/reference/cli.md"}'),r={name:"ar/reference/cli.md"};function s(l,t,i,n,h,c){return d(),o("div",null,[...t[0]||(t[0]=[a('<h1 id="مرجع-سطر-الأوامر-cli" tabindex="-1">مرجع سطر الأوامر (CLI) <a class="header-anchor" href="#مرجع-سطر-الأوامر-cli" aria-label="Permalink to &quot;مرجع سطر الأوامر (CLI)&quot;">​</a></h1><p>كل أوامر <code>reelforge</code> وخياراته، مولّدة من تعريف الأوامر في <code>packages/cli/src/index.ts</code>. على Windows شغّل <code>reelforge.cmd</code>، وعلى macOS وLinux شغّل <code>./reelforge</code>، أو <code>pnpm reelforge</code> من نسخة المصدر. رموز الخروج: <code>0</code> نجاح، و<code>1</code> فشل (أو أخطاء تحقق)، و<code>2</code> خطأ في طريقة الاستخدام. يشرح <a href="./../guide/command-line.html">دليل سطر الأوامر</a> متغيرات البيئة وطرق العمل الشائعة.</p><blockquote><p><strong>ملاحظة:</strong> هذه الصفحة مولّدة من الكود. العناوين والشرح بالعربية، أما الأوصاف داخل الجداول فتُقرأ من الكود وتبقى بالإنجليزية.</p></blockquote><h2 id="الخيارات-العامة" tabindex="-1">الخيارات العامة <a class="header-anchor" href="#الخيارات-العامة" aria-label="Permalink to &quot;الخيارات العامة&quot;">​</a></h2><p>تُكتب هذه الخيارات قبل أي أمر أو بعده.</p><table tabindex="0"><thead><tr><th>الخيار</th><th>الوصف</th><th>الافتراضي</th><th>إلزامي</th></tr></thead><tbody><tr><td><code>-V, --version</code></td><td>output the version number</td><td></td><td></td></tr><tr><td><code>--verbose</code></td><td>more output (info messages, logs)</td><td></td><td></td></tr><tr><td><code>--json</code></td><td>machine-readable JSON output</td><td></td><td></td></tr><tr><td><code>--root &lt;dir&gt;</code></td><td>project root (default: $REELFORGE_ROOT or the current directory)</td><td></td><td></td></tr></tbody></table><h2 id="الأوامر" tabindex="-1">الأوامر <a class="header-anchor" href="#الأوامر" aria-label="Permalink to &quot;الأوامر&quot;">​</a></h2><table tabindex="0"><thead><tr><th>الأمر</th><th>الوصف</th></tr></thead><tbody><tr><td><a href="#reelforge-studio"><code>reelforge studio</code></a></td><td>open the project dashboard: create episodes, upload voice, open the editor, validate and render</td></tr><tr><td><a href="#reelforge-new"><code>reelforge new</code></a></td><td>create episodes/&lt;id&gt;/episode.yaml from a commented template</td></tr><tr><td><a href="#reelforge-packs"><code>reelforge packs</code></a></td><td>list industry packs and their templates with slots</td></tr><tr><td><a href="#reelforge-cue"><code>reelforge cue</code></a></td><td>open the editor in Cues mode: mark when each line starts (writes cues.json)</td></tr><tr><td><a href="#reelforge-align"><code>reelforge align</code></a></td><td>mark cues automatically from the voice recording (lines and words; writes cues.json)</td></tr><tr><td><a href="#reelforge-edit"><code>reelforge edit</code></a></td><td>open the visual editor: canvas, layers, inspector and timeline (writes episode.yaml)</td></tr><tr><td><a href="#reelforge-dev"><code>reelforge dev</code></a></td><td>open the editor in Review mode: checks, safe zones, element outlines</td></tr><tr><td><a href="#reelforge-validate"><code>reelforge validate</code></a></td><td>check schema, cues, timing, layout, safe zones and text overflow</td></tr><tr><td><a href="#reelforge-render"><code>reelforge render</code></a></td><td>render master + share MP4, SRT, contact sheet and publish.md</td></tr><tr><td><a href="#reelforge-snap"><code>reelforge snap</code></a></td><td>write PNG frames at times (seconds or time expressions) and a contact sheet</td></tr><tr><td><a href="#reelforge-doctor"><code>reelforge doctor</code></a></td><td>check Node, ffmpeg, Chromium and fonts; print install steps</td></tr><tr><td><a href="#reelforge-theme-new"><code>reelforge theme new</code></a></td><td>generate a complete themes/&lt;name&gt;.theme.yaml (WCAG AA contrast) from one accent color</td></tr><tr><td><a href="#reelforge-mcp"><code>reelforge mcp</code></a></td><td>run the Model Context Protocol server on stdio (for AI assistants and agents)</td></tr><tr><td><a href="#reelforge-schema"><code>reelforge schema</code></a></td><td>write the episode JSON Schema (editor autocompletion)</td></tr></tbody></table><h2 id="reelforge-studio" tabindex="-1">reelforge studio <a class="header-anchor" href="#reelforge-studio" aria-label="Permalink to &quot;reelforge studio&quot;">​</a></h2><p>open the project dashboard: create episodes, upload voice, open the editor, validate and render</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>reelforge studio [options]</span></span></code></pre></div><table tabindex="0"><thead><tr><th>الخيار</th><th>الوصف</th><th>الافتراضي</th><th>إلزامي</th></tr></thead><tbody><tr><td><code>--port &lt;port&gt;</code></td><td>port (default 4310 or $REELFORGE_PORT)</td><td></td><td></td></tr><tr><td><code>--host &lt;address&gt;</code></td><td>bind address (default 127.0.0.1 or $REELFORGE_HOST); other addresses require the bearer token</td><td></td><td></td></tr><tr><td><code>--no-open</code></td><td>do not open the browser</td><td></td><td></td></tr></tbody></table><h2 id="reelforge-new" tabindex="-1">reelforge new <a class="header-anchor" href="#reelforge-new" aria-label="Permalink to &quot;reelforge new&quot;">​</a></h2><p>create episodes/&lt;id&gt;/episode.yaml from a commented template</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>reelforge new [options] &lt;id&gt;</span></span></code></pre></div><table tabindex="0"><thead><tr><th>الوسيط</th><th>الوصف</th><th>إلزامي</th></tr></thead><tbody><tr><td><code>id</code></td><td>episode id (slug)</td><td>نعم</td></tr></tbody></table><table tabindex="0"><thead><tr><th>الخيار</th><th>الوصف</th><th>الافتراضي</th><th>إلزامي</th></tr></thead><tbody><tr><td><code>--series &lt;name&gt;</code></td><td>series name shown in the header</td><td></td><td></td></tr><tr><td><code>--episode &lt;n&gt;</code></td><td>episode number</td><td></td><td></td></tr><tr><td><code>--lang &lt;en|ar&gt;</code></td><td>language of the template script (default en)</td><td></td><td></td></tr><tr><td><code>--pack &lt;id&gt;</code></td><td>start from an industry pack template (see <code>reelforge packs</code>)</td><td></td><td></td></tr><tr><td><code>--template &lt;id&gt;</code></td><td>template of the pack (default: the pack&#39;s first template)</td><td></td><td></td></tr><tr><td><code>--slot &lt;key=value&gt;</code></td><td>template slot value (repeatable); missing slots keep their defaults</td><td></td><td></td></tr></tbody></table><h2 id="reelforge-packs" tabindex="-1">reelforge packs <a class="header-anchor" href="#reelforge-packs" aria-label="Permalink to &quot;reelforge packs&quot;">​</a></h2><p>list industry packs and their templates with slots</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>reelforge packs [options]</span></span></code></pre></div><table tabindex="0"><thead><tr><th>الخيار</th><th>الوصف</th><th>الافتراضي</th><th>إلزامي</th></tr></thead><tbody><tr><td><code>--lang &lt;en|ar&gt;</code></td><td>language of names and slot defaults (default en)</td><td></td><td></td></tr></tbody></table><h2 id="reelforge-cue" tabindex="-1">reelforge cue <a class="header-anchor" href="#reelforge-cue" aria-label="Permalink to &quot;reelforge cue&quot;">​</a></h2><p>open the editor in Cues mode: mark when each line starts (writes cues.json)</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>reelforge cue [options] &lt;id&gt;</span></span></code></pre></div><table tabindex="0"><thead><tr><th>الوسيط</th><th>الوصف</th><th>إلزامي</th></tr></thead><tbody><tr><td><code>id</code></td><td>episode id or path</td><td>نعم</td></tr></tbody></table><table tabindex="0"><thead><tr><th>الخيار</th><th>الوصف</th><th>الافتراضي</th><th>إلزامي</th></tr></thead><tbody><tr><td><code>--draft</code></td><td>write estimated cues instead (preview before recording)</td><td></td><td></td></tr><tr><td><code>--port &lt;port&gt;</code></td><td>port (default 4317 or $REELFORGE_PORT)</td><td></td><td></td></tr><tr><td><code>--preset &lt;name&gt;</code></td><td>override meta.preset</td><td></td><td></td></tr><tr><td><code>--no-open</code></td><td>do not open the browser</td><td></td><td></td></tr></tbody></table><h2 id="reelforge-align" tabindex="-1">reelforge align <a class="header-anchor" href="#reelforge-align" aria-label="Permalink to &quot;reelforge align&quot;">​</a></h2><p>mark cues automatically from the voice recording (lines and words; writes cues.json)</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>reelforge align [options] [id]</span></span></code></pre></div><table tabindex="0"><thead><tr><th>الوسيط</th><th>الوصف</th><th>إلزامي</th></tr></thead><tbody><tr><td><code>id</code></td><td>episode id or path</td><td></td></tr></tbody></table><table tabindex="0"><thead><tr><th>الخيار</th><th>الوصف</th><th>الافتراضي</th><th>إلزامي</th></tr></thead><tbody><tr><td><code>--engine &lt;name&gt;</code></td><td>auto: whisper when installed, else dsp (إحدى القيم <code>auto</code>, <code>dsp</code>, <code>whisper</code>)</td><td></td><td></td></tr><tr><td><code>--model &lt;size&gt;</code></td><td>whisper model size (default base) (إحدى القيم <code>tiny</code>, <code>base</code>, <code>small</code>)</td><td></td><td></td></tr><tr><td><code>--no-vad</code></td><td>detect speech by energy only (skip Silero VAD)</td><td></td><td></td></tr><tr><td><code>--no-words</code></td><td>only line cues</td><td></td><td></td></tr><tr><td><code>--force</code></td><td>replace cues you marked by hand</td><td></td><td></td></tr><tr><td><code>--dry-run</code></td><td>print the result without writing cues.json</td><td></td><td></td></tr><tr><td><code>--setup</code></td><td>install the optional speech models (one time, ~180 MB in the user cache)</td><td></td><td></td></tr><tr><td><code>--status</code></td><td>show which speech models are installed</td><td></td><td></td></tr></tbody></table><h2 id="reelforge-edit" tabindex="-1">reelforge edit <a class="header-anchor" href="#reelforge-edit" aria-label="Permalink to &quot;reelforge edit&quot;">​</a></h2><p>open the visual editor: canvas, layers, inspector and timeline (writes episode.yaml)</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>reelforge edit [options] &lt;id&gt;</span></span></code></pre></div><table tabindex="0"><thead><tr><th>الوسيط</th><th>الوصف</th><th>إلزامي</th></tr></thead><tbody><tr><td><code>id</code></td><td>episode id or path</td><td>نعم</td></tr></tbody></table><table tabindex="0"><thead><tr><th>الخيار</th><th>الوصف</th><th>الافتراضي</th><th>إلزامي</th></tr></thead><tbody><tr><td><code>--port &lt;port&gt;</code></td><td>port (default 4317 or $REELFORGE_PORT)</td><td></td><td></td></tr><tr><td><code>--preset &lt;name&gt;</code></td><td>override meta.preset</td><td></td><td></td></tr><tr><td><code>--no-open</code></td><td>do not open the browser</td><td></td><td></td></tr></tbody></table><h2 id="reelforge-dev" tabindex="-1">reelforge dev <a class="header-anchor" href="#reelforge-dev" aria-label="Permalink to &quot;reelforge dev&quot;">​</a></h2><p>open the editor in Review mode: checks, safe zones, element outlines</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>reelforge dev [options] &lt;id&gt;</span></span></code></pre></div><table tabindex="0"><thead><tr><th>الوسيط</th><th>الوصف</th><th>إلزامي</th></tr></thead><tbody><tr><td><code>id</code></td><td>episode id or path</td><td>نعم</td></tr></tbody></table><table tabindex="0"><thead><tr><th>الخيار</th><th>الوصف</th><th>الافتراضي</th><th>إلزامي</th></tr></thead><tbody><tr><td><code>--port &lt;port&gt;</code></td><td>port (default 4317 or $REELFORGE_PORT)</td><td></td><td></td></tr><tr><td><code>--preset &lt;name&gt;</code></td><td>override meta.preset</td><td></td><td></td></tr><tr><td><code>--no-open</code></td><td>do not open the browser</td><td></td><td></td></tr></tbody></table><h2 id="reelforge-validate" tabindex="-1">reelforge validate <a class="header-anchor" href="#reelforge-validate" aria-label="Permalink to &quot;reelforge validate&quot;">​</a></h2><p>check schema, cues, timing, layout, safe zones and text overflow</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>reelforge validate [options] &lt;id&gt;</span></span></code></pre></div><table tabindex="0"><thead><tr><th>الوسيط</th><th>الوصف</th><th>إلزامي</th></tr></thead><tbody><tr><td><code>id</code></td><td>episode id or path</td><td>نعم</td></tr></tbody></table><table tabindex="0"><thead><tr><th>الخيار</th><th>الوصف</th><th>الافتراضي</th><th>إلزامي</th></tr></thead><tbody><tr><td><code>--strict</code></td><td>fail on warnings too</td><td></td><td></td></tr><tr><td><code>--preset &lt;name&gt;</code></td><td>override meta.preset</td><td></td><td></td></tr><tr><td><code>--no-measure</code></td><td>skip the headless V-9/V-10 checks</td><td></td><td></td></tr></tbody></table><h2 id="reelforge-render" tabindex="-1">reelforge render <a class="header-anchor" href="#reelforge-render" aria-label="Permalink to &quot;reelforge render&quot;">​</a></h2><p>render master + share MP4, SRT, contact sheet and publish.md</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>reelforge render [options] [id]</span></span></code></pre></div><table tabindex="0"><thead><tr><th>الوسيط</th><th>الوصف</th><th>إلزامي</th></tr></thead><tbody><tr><td><code>id</code></td><td>episode id or path (or a folder of episodes with --all)</td><td></td></tr></tbody></table><table tabindex="0"><thead><tr><th>الخيار</th><th>الوصف</th><th>الافتراضي</th><th>إلزامي</th></tr></thead><tbody><tr><td><code>--all</code></td><td>render every episode in episodes/ (or in the given folder)</td><td></td><td></td></tr><tr><td><code>--preset &lt;name&gt;</code></td><td>tiktok | reels | shorts (default: meta.preset, $REELFORGE_PRESET)</td><td></td><td></td></tr><tr><td><code>--workers &lt;n&gt;</code></td><td>parallel Chromium workers (default: CPU cores − 1, $REELFORGE_WORKERS)</td><td></td><td></td></tr><tr><td><code>--from &lt;t&gt;</code></td><td>partial render start (seconds) → &lt;id&gt;.part.mp4</td><td></td><td></td></tr><tr><td><code>--to &lt;t&gt;</code></td><td>partial render end (seconds)</td><td></td><td></td></tr><tr><td><code>--share-size &lt;MB&gt;</code></td><td>share file size cap (default 28, $REELFORGE_SHARE_SIZE)</td><td></td><td></td></tr><tr><td><code>--no-sfx</code></td><td>render without sound effects</td><td></td><td></td></tr><tr><td><code>--no-share</code></td><td>skip the share file</td><td></td><td></td></tr><tr><td><code>--lossless</code></td><td>capture PNG frames instead of JPEG</td><td></td><td></td></tr><tr><td><code>--fast</code></td><td>faster master/share encoding (preset medium)</td><td></td><td></td></tr><tr><td><code>--silent</code></td><td>allow rendering without a voice recording</td><td></td><td></td></tr><tr><td><code>--keep-tmp</code></td><td>keep out/.tmp/&lt;run-id&gt;/ on failure</td><td></td><td></td></tr><tr><td><code>--no-measure</code></td><td>skip the headless V-9/V-10 checks</td><td></td><td></td></tr><tr><td><code>--denoise</code></td><td>remove background noise from the voice (default: audio.denoise)</td><td></td><td></td></tr><tr><td><code>--no-denoise</code></td><td>keep the voice as recorded, even when audio.denoise is true</td><td></td><td></td></tr></tbody></table><h2 id="reelforge-snap" tabindex="-1">reelforge snap <a class="header-anchor" href="#reelforge-snap" aria-label="Permalink to &quot;reelforge snap&quot;">​</a></h2><p>write PNG frames at times (seconds or time expressions) and a contact sheet</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>reelforge snap [options] &lt;id&gt; [times...]</span></span></code></pre></div><table tabindex="0"><thead><tr><th>الوسيط</th><th>الوصف</th><th>إلزامي</th></tr></thead><tbody><tr><td><code>id</code></td><td>episode id or path</td><td>نعم</td></tr><tr><td><code>times...</code></td><td>times: 12.5, 12.5s, l7, &quot;l7:&#39;word&#39;&quot;, l7.end+0.2</td><td></td></tr></tbody></table><table tabindex="0"><thead><tr><th>الخيار</th><th>الوصف</th><th>الافتراضي</th><th>إلزامي</th></tr></thead><tbody><tr><td><code>--every &lt;seconds&gt;</code></td><td>one frame every N seconds</td><td></td><td></td></tr><tr><td><code>--out &lt;dir&gt;</code></td><td>output folder (default out/snaps)</td><td></td><td></td></tr><tr><td><code>--preset &lt;name&gt;</code></td><td>override meta.preset</td><td></td><td></td></tr><tr><td><code>--cover</code></td><td>write a single 1080×1920 cover image to out/&lt;id&gt;.cover.png</td><td></td><td></td></tr></tbody></table><h2 id="reelforge-doctor" tabindex="-1">reelforge doctor <a class="header-anchor" href="#reelforge-doctor" aria-label="Permalink to &quot;reelforge doctor&quot;">​</a></h2><p>check Node, ffmpeg, Chromium and fonts; print install steps</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>reelforge doctor [options]</span></span></code></pre></div><table tabindex="0"><thead><tr><th>الخيار</th><th>الوصف</th><th>الافتراضي</th><th>إلزامي</th></tr></thead><tbody><tr><td><code>--fix</code></td><td>install the pinned Chromium if missing</td><td></td><td></td></tr></tbody></table><h2 id="reelforge-theme-new" tabindex="-1">reelforge theme new <a class="header-anchor" href="#reelforge-theme-new" aria-label="Permalink to &quot;reelforge theme new&quot;">​</a></h2><p>generate a complete themes/&lt;name&gt;.theme.yaml (WCAG AA contrast) from one accent color</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>reelforge theme new [options] &lt;name&gt;</span></span></code></pre></div><table tabindex="0"><thead><tr><th>الوسيط</th><th>الوصف</th><th>إلزامي</th></tr></thead><tbody><tr><td><code>name</code></td><td>theme name (slug)</td><td>نعم</td></tr></tbody></table><table tabindex="0"><thead><tr><th>الخيار</th><th>الوصف</th><th>الافتراضي</th><th>إلزامي</th></tr></thead><tbody><tr><td><code>--accent &lt;hex&gt;</code></td><td>accent color, e.g. #b8ff3c (adjusted only if it would be hard to read)</td><td></td><td>نعم</td></tr><tr><td><code>--mode &lt;mode&gt;</code></td><td>light or dark background (default dark)</td><td></td><td></td></tr><tr><td><code>--font &lt;family&gt;</code></td><td>bundled font for its slot (display, mono or arabic): Space Grotesk, JetBrains Mono, Cairo, Inter, Manrope, Playfair Display, Noto Kufi Arabic, Noto Naskh Arabic, Readex Pro</td><td></td><td></td></tr><tr><td><code>--out &lt;file&gt;</code></td><td>output file</td><td></td><td></td></tr></tbody></table><h2 id="reelforge-mcp" tabindex="-1">reelforge mcp <a class="header-anchor" href="#reelforge-mcp" aria-label="Permalink to &quot;reelforge mcp&quot;">​</a></h2><p>run the Model Context Protocol server on stdio (for AI assistants and agents)</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>reelforge mcp [options]</span></span></code></pre></div><table tabindex="0"><thead><tr><th>الخيار</th><th>الوصف</th><th>الافتراضي</th><th>إلزامي</th></tr></thead><tbody><tr><td><code>--toolsets &lt;list&gt;</code></td><td>only these toolsets: basic, design, render or all (default all)</td><td></td><td></td></tr></tbody></table><h2 id="reelforge-schema" tabindex="-1">reelforge schema <a class="header-anchor" href="#reelforge-schema" aria-label="Permalink to &quot;reelforge schema&quot;">​</a></h2><p>write the episode JSON Schema (editor autocompletion)</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>reelforge schema [options]</span></span></code></pre></div><table tabindex="0"><thead><tr><th>الخيار</th><th>الوصف</th><th>الافتراضي</th><th>إلزامي</th></tr></thead><tbody><tr><td><code>--out &lt;file&gt;</code></td><td>output file (default schema/episode.schema.json)</td><td></td><td></td></tr></tbody></table>',73)])])}const b=e(r,[["render",s]]);export{g as __pageData,b as default};
